    if(memcmp(header + 0x3b, "NT2", 3) == 0) {cpak = true; rpak = true;}                              //Turok 2 - Seeds of Evil [Violence Killer - Turok New Generation (J)]
    if(memcmp(header + 0x3b, "NTK", 3) == 0) {cpak = true; rpak = true;}                              //Turok 3 - Shadow of Oblivion
    if(memcmp(header + 0x3b, "NSB", 3) == 0) {cpak = true; rpak = true;}                              //Twisted Edge - Extreme Snowboarding [King Hill 64 - Extreme Snowboarding (J)]
