    if(memcmp(header + 0x3b, "NVR", 3) == 0) {cpak = true;}                                           //Virtual Pool 64
    if(memcmp(header + 0x3b, "NWV", 3) == 0) {cpak = true; rpak = true;}                              //WCW: Backstage Assault
    if(memcmp(header + 0x3b, "NWM", 3) == 0) {cpak = true; rpak = true;}                              //WCW: Mayhem
    if(memcmp(header + 0x3b, "NW3", 3) == 0) {cpak = true; rpak = true;}                              //WCW: Nitro
    if(memcmp(header + 0x3b, "NWN", 3) == 0) {cpak = true; rpak = true;}                              //WCW vs. nWo - World Tour
    if(memcmp(header + 0x3b, "NWW", 3) == 0) {cpak = true; rpak = true;}                              //WWF: War Zone
